contracts/erc7529/ERC7529Upgradeable.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import {IERC7529} from "./IERC7529.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

abstract contract ERC7529Upgradeable is IERC7529, Initializable {
    /* Storage Variables */

    /// @custom:storage-location erc7201:snickerdoodle.erc7529
    struct ERC7529Storage {
        /// @dev Mapping of trusted eTLD+1s
        mapping(bytes32 => bool) domains;
    }

    // keccak256(abi.encode(uint256(keccak256("snickerdoodle.erc7529")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant ERC7529StorageLocation =
        0x29912872bb1868dd74efe86230a05098a24ae1f39d64ec2129d982442801ac00;

    error InvalideETLD1Domain(string domain);

    function _getERC7529Storage()
        private
        pure
        returns (ERC7529Storage storage $)
    {
        assembly {
            $.slot := ERC7529StorageLocation
        }
    }

    function __ERC7529_init() internal onlyInitializing {}

    function __ERC7529_init_unchained() internal onlyInitializing {}

    /// @notice a getter function that takes an eTLD+1 domain string and returns true if associated with the contract
    /// @param domain a string representing an eTLD+1 domain
    function checkERC7529Domain(string calldata domain) external view returns (bool) {
        ERC7529Storage storage $ = _getERC7529Storage();
        return $.domains[keccak256(abi.encodePacked(domain))];
    }

    /// @notice an authenticated method to add an eTLD+1 domain
    /// @param domain a string representing an eTLD+1 domain associated with the contract
    function _addDomain(string memory domain) internal virtual {
        ERC7529Storage storage $ = _getERC7529Storage();
        $.domains[keccak256(abi.encodePacked(domain))] = true;
        emit AddERC7529Domain(domain);
    }

    /// @notice an authenticated method to remove an eTLD+1 domain
    /// @param domain a string representing an eTLD+1 domain that is no longer associated with the contract
    function _removeDomain(string memory domain) internal virtual {
        ERC7529Storage storage $ = _getERC7529Storage();
        require($.domains[keccak256(abi.encodePacked(domain))] == true, InvalideETLD1Domain(domain));
        $.domains[keccak256(abi.encodePacked(domain))] = false;
        emit RemoveERC7529Domain(domain);
    }
}

contracts/erc7529/IERC7529.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC7529 {
    /* EVENTS */

    /// @notice Emitted when a domain is added
    /// @param domain Domain url added
    event AddERC7529Domain(string domain);

    /// @notice Emitted when a domain is removed
    /// @param domain Domain url removed
    event RemoveERC7529Domain(string domain);

    /* Functions */

    function checkERC7529Domain(string calldata domain) external view returns (bool);
}

contracts/oapp-upgradeable/OAppCoreUpgra.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.22;

import { OwnableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import { IOAppCore, ILayerZeroEndpointV2 } from "@layerzerolabs/lz-evm-oapp-v2/contracts/oapp/interfaces/IOAppCore.sol";

/**
 * @title OAppCoreUpgradeable
 * @dev Abstract upgradable contract implementing the IOAppCore interface with basic OApp configurations.
 */
abstract contract OAppCoreUpgradeable is IOAppCore, OwnableUpgradeable {

    // The LayerZero endpoint associated with the given OApp
    // Mapping to store peers associated with corresponding endpoints
    struct OAppCoreStorage {
        ILayerZeroEndpointV2 endpoint;
        mapping(uint32 eid => bytes32 peer) peers;
    }

    // keccak256(abi.encode(uint256(keccak256("snickerdoodle.storage.OAppCore")) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant OAppCoreStorageLocation  =
        0x6a0d2aba043cb44543431324191adac77f4308da25e5eafb339b7d48709cf900;


    /**
     * @dev Initializer to initialize the OAppCoreUpgradeable with the provided endpoint and delegate.
     * @param _endpoint The address of the LOCAL Layer Zero endpoint.
     * @param _delegate The delegate capable of making OApp configurations inside of the endpoint.
     *
     * @dev The delegate typically should be set as the owner of the contract.
     */
    function __OAppCore_init(address _endpoint, address _delegate) internal onlyInitializing {
        __OAppCore_init_unchained(_endpoint, _delegate);
    }

    function __OAppCore_init_unchained(address _endpoint, address _delegate) internal onlyInitializing {
        OAppCoreStorage storage $ = _getOAppCoreStorage();

        $.endpoint = ILayerZeroEndpointV2(_endpoint);

        if (_delegate == address(0)) revert InvalidDelegate();
        $.endpoint.setDelegate(_delegate);
    }

    function _getOAppCoreStorage()
        internal // To be accessed by OAppSenderUpgradeable and OAppReceiverUpgradeable
        pure
        returns (OAppCoreStorage storage $)
    {
        assembly {
            $.slot := OAppCoreStorageLocation
        }
    }

    /**
     * @notice Retrieves the LayerZero endpoint associated with the OApp.
     * @dev Required implementation of the IOAppCore interface.
     * @return iEndpoint The LayerZero endpoint as an interface.
     */
    function endpoint() external view returns (ILayerZeroEndpointV2 iEndpoint) {
        OAppCoreStorage storage $ = _getOAppCoreStorage();
        return $.endpoint;
    }

    /**
     * @notice Retrieves the peer (OApp) associated with a corresponding endpoint.
     * @dev Required implementation of the IOAppCore interface.
     * @param _eid The endpoint ID.
     * @return peer The peer address (OApp instance) associated with the corresponding endpoint.
     */
    function peers(uint32 _eid) external view returns (bytes32 peer) {
        OAppCoreStorage storage $ = _getOAppCoreStorage();
        return $.peers[_eid];
    }

    /**
     * @notice Sets the peer address (OApp instance) for a corresponding endpoint.
     * @param _eid The endpoint ID.
     * @param _peer The address of the peer to be associated with the corresponding endpoint.
     *
     * @dev Only the owner/admin of the OApp can call this function.
     * @dev Indicates that the peer is trusted to send LayerZero messages to this OApp.
     * @dev Set this to bytes32(0) to remove the peer address.
     * @dev Peer is a bytes32 to accommodate non-evm chains.
     */
    function setPeer(uint32 _eid, bytes32 _peer) public virtual onlyOwner {
        OAppCoreStorage storage $ = _getOAppCoreStorage();
        $.peers[_eid] = _peer;
        emit PeerSet(_eid, _peer);
    }

    /**
     * @notice Internal function to get the peer address associated with a specific endpoint; reverts if NOT set.
     * ie. the peer is set to bytes32(0).
     * @param _eid The endpoint ID.
     * @return peer The address of the peer associated with the specified endpoint.
     */
    function _getPeerOrRevert(uint32 _eid) internal view virtual returns (bytes32) {
        OAppCoreStorage storage $ = _getOAppCoreStorage();
        bytes32 peer = $.peers[_eid];
        if (peer == bytes32(0)) revert NoPeer(_eid);
        return peer;
    }

    /**
     * @notice Sets the delegate address for the OApp.
     * @param _delegate The address of the delegate to be set.
     *
     * @dev Only the owner/admin of the OApp can call this function.
     * @dev Provides the ability for a delegate to set configs, on behalf of the OApp, directly on the Endpoint contract.
     */
    function setDelegate(address _delegate) public onlyOwner {
        OAppCoreStorage storage $ = _getOAppCoreStorage();
        $.endpoint.setDelegate(_delegate);
    }
}

